function PageTitle({eyebrow,title,sub,locale}){const evidence=locale==="en"?"Evidence-first":locale==="es"?"Evidencia primero":"Evidência primeiro";return <div className="page-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{sub}</p></div><div className="secure"><ShieldCheck size={16}/> {evidence}</div></div>}
