function Governance({me,locale}){
 const t=locale==="en"?{ey:"GOVERNANCE",title:"Control without ",accent:"friction.",sub:"Tenant isolation, RBAC, scopes and operational traceability.",users:"USERS",active:"active",roles:"CUSTOM ROLES",tenantScoped:"tenant scoped",scopes:"SCOPES",bounds:"discovery boundaries",session:"SESSION ROLE",manage:"management enabled",least:"least privilege",identity:"Identity",current:"current session",posture:"Security posture",platform:"platform",isolation:"Tenant isolation",enforced:"ENFORCED",scoped:"Scoped discovery",audit:"Audit trail",auditActive:"ACTIVE",save:"Save",assign:"Assign scope…",loading:"Loading…",edit:"Edit user",disable:"Disable user",enable:"Enable user",noUsers:"No users in tenant",noUsersText:"Add users to start delegating access.",custom:"Custom Roles",roleName:"Role name · e.g. SOC Read Only",create:"Create custom role",noRoles:"No custom role",noRolesText:"Create specific roles to separate tenant responsibilities.",permissions:"permissions"}:locale==="es"?{ey:"GOBERNANZA",title:"Control sin ",accent:"fricción.",sub:"Aislamiento por tenant, RBAC, scopes y trazabilidad operativa.",users:"USUARIOS",active:"activos",roles:"ROLES PERSONALIZADOS",tenantScoped:"limitados al tenant",scopes:"SCOPES",bounds:"límites de discovery",session:"ROL DE SESIÓN",manage:"gestión habilitada",least:"menor privilegio",identity:"Identidad",current:"sesión actual",posture:"Postura de seguridad",platform:"plataforma",isolation:"Aislamiento por tenant",enforced:"APLICADO",scoped:"Discovery por alcance",audit:"Trazabilidad",auditActive:"ACTIVA",save:"Guardar",assign:"Asignar scope…",loading:"Cargando…",edit:"Editar usuario",disable:"Desactivar usuario",enable:"Activar usuario",noUsers:"Sin usuarios en el tenant",noUsersText:"Agregue usuarios para comenzar a delegar acceso.",custom:"Roles personalizados",roleName:"Nombre del rol · ej.: SOC Read Only",create:"Crear rol personalizado",noRoles:"Sin roles personalizados",noRolesText:"Cree roles específicos para separar responsabilidades del tenant.",permissions:"permisos"}:{ey:"GOVERNANÇA",title:"Controle sem ",accent:"atrito.",sub:"Isolamento por tenant, RBAC, scopes e rastreabilidade operacional.",users:"USUÁRIOS",active:"ativos",roles:"ROLES CUSTOMIZADAS",tenantScoped:"limitadas ao tenant",scopes:"SCOPES",bounds:"limites de discovery",session:"ROLE DA SESSÃO",manage:"gestão habilitada",least:"menor privilégio",identity:"Identidade",current:"sessão atual",posture:"Postura de segurança",platform:"plataforma",isolation:"Isolamento por tenant",enforced:"APLICADO",scoped:"Discovery por escopo",audit:"Trilha de auditoria",auditActive:"ATIVA",save:"Salvar",assign:"Atribuir scope…",loading:"Carregando…",edit:"Editar usuário",disable:"Desativar usuário",enable:"Ativar usuário",noUsers:"Nenhum usuário no tenant",noUsersText:"Cadastre usuários para começar a delegar acesso.",custom:"Roles customizadas",roleName:"Nome da role · ex.: SOC Read Only",create:"Criar role customizada",noRoles:"Nenhuma role customizada",noRolesText:"Crie roles específicas para separar responsabilidades do tenant.",permissions:"permissões"};
 const[users,setUsers]=useState([]),[roles,setRoles]=useState([]),[perms,setPerms]=useState([]),[scopes,setScopes]=useState([]),[userScopes,setUserScopes]=useState([]),[loading,setLoading]=useState(true),[edit,setEdit]=useState(null),[roleForm,setRoleForm]=useState({name:"",permissions:[]}),[error,setError]=useState("");
 const canManage=["admin","superadmin"].includes(me?.role);
 const load=async()=>{setLoading(true);const [u,r,p,s]=await Promise.all([req("/api/v1/users"),req("/api/v1/rbac/custom-roles"),req("/api/v1/rbac/permissions"),req("/api/v1/scopes")]);if(u.ok)setUsers(await u.json());if(r.ok)setRoles(await r.json());if(p.ok)setPerms((await p.json()).permissions||[]);if(s.ok)setScopes(await s.json());setLoading(false)};
 useEffect(()=>{load()},[]);
 const loadUserScopes=async u=>{const r=await req("/api/v1/users/"+u.id+"/scopes");setUserScopes(r.ok?await r.json():[])};
 const assignScope=async scopeId=>{if(!edit)return;const r=await req("/api/v1/users/"+edit.id+"/scopes",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({scope_id:scopeId,active:true})});if(!r.ok)return setError((await r.json()).detail||"Falha ao atribuir scope");loadUserScopes(edit)};
 const save=async e=>{e.preventDefault();const r=await req("/api/v1/users/"+edit.id,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:edit.name,role:edit.role})});if(!r.ok)return setError((await r.json()).detail||"Falha");setEdit(null);load()};
 const toggle=async u=>{const r=await req("/api/v1/users/"+u.id+"/active",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({active:!u.active})});if(!r.ok)setError((await r.json()).detail||"Falha");else load()};
 const createRole=async e=>{e.preventDefault();const r=await req("/api/v1/rbac/custom-roles",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(roleForm)});if(!r.ok)return setError((await r.json()).detail||"Falha ao criar role");setRoleForm({name:"",permissions:[]});load()};
 return <><PageTitle locale={locale} eyebrow={t.ey} title={<>{t.title}<i>{t.accent}</i></>} sub={t.sub}/>
 <div className="governance-kpis"><div><span>{t.users}</span><b>{users.length}</b><small>{users.filter(u=>u.active).length} {t.active}</small></div><div><span>{t.roles}</span><b>{roles.length}</b><small>{t.tenantScoped}</small></div><div><span>SCOPES</span><b>{scopes.length}</b><small>{t.bounds}</small></div><div><span>{t.session}</span><b className="role-value">{me?.role||"—"}</b><small>{canManage?t.manage:t.least}</small></div></div>
 <div className="grid-main"><section className="panel"><PanelHead title={t.identity} meta={t.current}/><div className="identity"><div className="avatar large">{(me?.name||"M").slice(0,1)}</div><div><h3>{me?.name}</h3><p>{me?.email}</p><span className="tag">{me?.role}</span><span className="tag">{me?.tenant_id}</span></div></div></section><section className="panel"><PanelHead title={t.posture} meta={t.platform}/><div className="security-list"><div><LockKeyhole/> {t.isolation} <b>{t.enforced}</b></div><div><Eye/> {t.scoped} <b>{t.enforced}</b></div><div><CheckCircle2/> {t.audit} <b>{t.auditActive}</b></div></div></section></div>
 <section className="panel"><PanelHead title={t.users} meta={users.length+" tenant users"}/>{error&&<div className="error">{error}</div>}
 {edit&&<><form onSubmit={save} className="governance-edit-form"><input required value={edit.name} onChange={e=>setEdit({...edit,name:e.target.value})}/><select value={edit.role} onChange={e=>setEdit({...edit,role:e.target.value})}>{["viewer","analyst","manager","admin",...roles.map(r=>r.name)].map(x=><option key={x}>{x}</option>)}</select><button className="primary">{t.save}</button><button type="button" className="icon-btn" onClick={()=>loadUserScopes(edit)}>Scopes</button></form><div className="security-list governance-scope-list">{userScopes.map(s=><div key={s.id}><span>{s.name} · {s.pattern}</span><em>{s.active?"ACTIVE":"INACTIVE"}</em></div>)}{canManage&&<div className="scope-assign"><select defaultValue="" onChange={e=>e.target.value&&assignScope(e.target.value)}><option value="">{t.assign}</option>{scopes.map(s=><option key={s.id} value={s.id}>{s.name} · {s.pattern}</option>)}</select></div>}</div></>}
 <div className="security-list governance-users">{loading?<div>{t.loading}</div>:users.length?users.map(u=><div key={u.id}><UserRound size={17}/><span>{u.name} · {u.email}</span><b>{u.role}</b><em>{u.active?"ACTIVE":"INACTIVE"}</em>{canManage&&<><button className="icon-btn" aria-label={t.edit} title={t.edit} onClick={()=>setEdit({...u})}>✎</button><button className="icon-btn" aria-label={u.active?t.disable:t.enable} title={u.active?t.disable:t.enable} onClick={()=>toggle(u)}>{u.active?"⏸":"▶"}</button></>}</div>):<EmptyState title={t.noUsers} text={t.noUsersText} compact/>}</div></section>
 <section className="panel"><PanelHead title={t.custom} meta={roles.length+" tenant roles"}/>{canManage&&<form onSubmit={createRole} className="governance-role-form"><input required placeholder={t.roleName} value={roleForm.name} onChange={e=>setRoleForm({...roleForm,name:e.target.value})}/><div className="security-list">{perms.map(p=><label key={p} className="permission-option"><input type="checkbox" checked={roleForm.permissions.includes(p)} onChange={e=>setRoleForm({...roleForm,permissions:e.target.checked?[...roleForm.permissions,p]:roleForm.permissions.filter(x=>x!==p)})}/>{p}</label>)}</div><button className="primary" disabled={!roleForm.permissions.length}>{t.create}</button></form>}<div className="security-list governance-role-list">{roles.length?roles.map(r=><div key={r.name}><Layers3 size={17}/><span>{r.name}</span><b>{r.permissions.length} {t.permissions}</b></div>):<EmptyState title={t.noRoles} text={t.noRolesText} compact/>}</div></section>
 </>}

function Meter({value}){return <div className="meter"><i style={{width:value+"%"}}/><span>{value}%</span></div>}
function AssetDrawer({id,onClose,locale}){const t=locale==="en"?{loading:"Loading Asset 360…",risk:"Risk",ownership:"Ownership",blast:"Blast Radius",evidence:"Evidence",why:"Why this matters",explainable:"explainable",findings:"Findings",dna:"Exposure DNA",fingerprint:"fingerprint",close:"Close Asset 360"}:locale==="es"?{loading:"Cargando Asset 360…",risk:"Riesgo",ownership:"Ownership",blast:"Radio de impacto",evidence:"Evidencia",why:"Por qué importa",explainable:"explicable",findings:"Hallazgos",dna:"ADN de exposición",fingerprint:"huella",close:"Cerrar Asset 360"}:{loading:"Carregando Asset 360…",risk:"Risco",ownership:"Ownership",blast:"Raio de impacto",evidence:"Evidências",why:"Por que isso importa",explainable:"explicável",findings:"Achados",dna:"DNA de exposição",fingerprint:"impressão digital",close:"Fechar Asset 360"};const[d,setD]=useState(null);useEffect(()=>{req("/api/v1/assets/"+id).then(r=>r.json()).then(setD)},[id]);return <div className="drawer-backdrop" onClick={e=>e.target===e.currentTarget&&onClose()}><aside className="drawer">{!d?<div className="loading">{t.loading}</div>:<><div className="drawer-head"><div><div className="eyebrow">ASSET 360</div><h2>{d.asset.value}</h2><p>{d.asset.type} · {d.asset.environment} · {d.asset.status}</p></div><button className="icon-btn" aria-label={t.close} title={t.close} onClick={onClose}><X/></button></div><div className="drawer-grid">{[[t.risk,d.risk.score],[t.ownership,d.ownership.score+"%"],[t.blast,d.blast_radius],[t.evidence,d.evidence.evidence_count]].map(x=><div className="drawer-stat" key={x[0]}><span>{x[0]}</span><b>{x[1]}</b></div>)}</div><div className="drawer-section"><PanelHead title={t.why} meta={t.explainable}/>{d.risk.rationale?.map(x=><div className="reason" key={x}><span>+</span>{x}</div>)}</div><div className="drawer-section"><PanelHead title={t.findings} meta={d.findings.length}/>{d.findings.map(f=><div className="finding-row" key={f.id}><div><b>{f.title}</b><span>{f.severity} · {f.status}</span></div><strong>{f.context_score}</strong></div>)}</div><div className="drawer-section"><PanelHead title={t.dna} meta={t.fingerprint}/><code>{d.exposure_dna?.fingerprint||"—"}</code><div className="evidence-row">{d.exposure_dna?.explainability?.map(x=><span key={x}>{x}</span>)}</div></div></>}</aside></div>}
